import org.joget.commons.util.LogUtil;
import java.net.HttpURLConnection;
import java.net.URL;
import java.io.OutputStream;
import java.io.InputStreamReader;
import java.io.BufferedReader;

// Récupère le label de la VM depuis les paramètres du lien (ex: ?id_vm=pipeline-ci)
String label = "#requestParam.id_vm#";

for (String containerName : rowKeys) {
    LogUtil.warn("Container à starter", containerName);
    LogUtil.warn("Label de la VM", label);

    HttpURLConnection connHTTP = null;
    BufferedReader reader = null;
    StringBuilder responseContent = new StringBuilder();

    try {
        URL url = new URL("http://127.0.0.1:5050/api/vm/docker/container/stop");
        connHTTP = (HttpURLConnection) url.openConnection();

        connHTTP.setRequestMethod("POST");
        connHTTP.setRequestProperty("Content-Type", "application/json");
        connHTTP.setRequestProperty("Accept", "application/json");

        // ✅ Headers personnalisés
        connHTTP.setRequestProperty("Label", label);
        connHTTP.setRequestProperty("Container-name", containerName);

        connHTTP.setDoOutput(true);
        OutputStream os = connHTTP.getOutputStream();
        os.write("{}".getBytes()); // Envoie un corps JSON vide
        os.flush();
        os.close();

        int status = connHTTP.getResponseCode();
        LogUtil.info("Code de réponse", String.valueOf(status));

        InputStreamReader streamReader = (status >= 300) ?
            new InputStreamReader(connHTTP.getErrorStream()) :
            new InputStreamReader(connHTTP.getInputStream());

        reader = new BufferedReader(streamReader);
        String line;
        while ((line = reader.readLine()) != null) {
            responseContent.append(line);
        }

        LogUtil.info("Réponse API", responseContent.toString());

    } catch (Exception e) {
        LogUtil.error("Erreur API Start Container", e, "Une erreur est survenue");
    } finally {
        if (connHTTP != null) connHTTP.disconnect();
        if (reader != null) try { reader.close(); } catch (Exception ignored) {}
    }
}

